import sys

def solve():
    lines = sys.stdin.read().split()
    cowphabet, heard = lines[0], lines[1]
    pos = {ch: i for i, ch in enumerate(cowphabet)}
    hums = 1
    for i in range(1, len(heard)):
        if pos[heard[i]] <= pos[heard[i - 1]]:
            hums += 1
    print(hums)

if __name__ == "__main__":
    solve()

