using namespace std;

int main() {
    string cowphabet, heard;
    cin >> cowphabet >> heard;
    int pos[26];
    for (int i = 0; i < 26; i++) pos[cowphabet[i] - 'a'] = i;
    int hums = 1;
    for (size_t i = 1; i < heard.size(); i++) {
        if (pos[heard[i] - 'a'] <= pos[heard[i - 1] - 'a']) {
            hums++;
        }
    }
    cout << hums << '\n';
    return 0;
}

