        Scanner sc = new Scanner(System.in);
        String cowphabet = sc.next();
        String heard = sc.next();
        int[] pos = new int[26];
        for (int i = 0; i < 26; i++) pos[cowphabet.charAt(i) - 'a'] = i;
        int hums = 1;
        for (int i = 1; i < heard.length(); i++) {
            if (pos[heard.charAt(i) - 'a'] <= pos[heard.charAt(i - 1) - 'a']) {
                hums++;
            }
        }
        System.out.println(hums);
    }
}

